"use client";
import Image from "next/image";
import { useState, useEffect } from "react";
import { getCookie, hasCookie } from "cookies-next";
import priceFormat from "@/helpers/priceFormat";
import postSubscribe from "@/services/subscribe";
import getDealTours from "@/services/dealTours";
import getDealToursCategories from "@/services/dealToursCategories";
import getTourPricing from "@/services/tourPricingService";
import ToursSkeleton from "../tours-skeleton";

const inputCls =
  "tw-w-full tw-rounded-lg tw-border tw-border-solid tw-border-[#d6d2de] tw-bg-white tw-px-3.5 tw-py-2.5 tw-text-sm tw-text-[#14101c] tw-outline-none tw-transition focus:tw-border-[#854ec9] focus:tw-shadow-[0_0_0_3px_rgba(133,78,201,0.12)]";

const CATEGORY_COLUMNS: { href: string; title: string; label: string }[][] = [
  [
    {
      href: "/worldwide-all-inclusive-tours#promotion_type=black_friday",
      title: "Worldwide All Inclusive Tours",
      label: "All Inclusive Tours",
    },
    {
      href: "/worldwide-anzac-day-tours#promotion_type=black_friday",
      title: "Anzac Day Tours",
      label: "Anzac Day Tours",
    },
    {
      href: "/worldwide-culinary-wine-food-and-tasting-tours#promotion_type=black_friday",
      title: "Worldwide Culinary, Wine, Food & Tasting Tours",
      label: "Culinary, Wine, Food & Tasting Tours",
    },
    {
      href: "/worldwide-culture-and-historical-tours#promotion_type=black_friday",
      title: "Worldwide Culture & Historical Tours",
      label: "Culture & Historical Tours",
    },
  ],
  [
    {
      href: "/worldwide-eco-tours#promotion_type=black_friday",
      title: "Worldwide Eco Tours",
      label: "Eco Tours",
    },
    {
      href: "/worldwide-family-holidays-tours#promotion_type=black_friday",
      title: "Worldwide Family Holidays Tours",
      label: "Family Holidays Tours",
    },
    {
      href: "/worldwide-honeymoon-tours#promotion_type=black_friday",
      title: "Worldwide Honeymoon Tours",
      label: "Honeymoon Tours",
    },
    {
      href: "/turkey-istanbul-tours#promotion_type=black_friday",
      title: "Turkey Istanbul Tours",
      label: "Istanbul Tours",
    },
  ],
  [
    {
      href: "/worldwide-luxury-travel-tours#promotion_type=black_friday",
      title: "Worldwide Luxury Travel Tours",
      label: "Luxury Travel Tours",
    },
    {
      href: "/worldwide-religious-tours#promotion_type=black_friday",
      title: "Worldwide Religious Tours",
      label: "Religious Tours",
    },
    {
      href: "/worldwide-women-art-tours#promotion_type=black_friday",
      title: "Worldwide Women Art Tours",
      label: "Women Art Tours",
    },
  ],
];

export default function LegendaryDecemberPage() {
  const defaultPricesValue = [
    {
      tourId: 0,
      price: 0,
      oldPrice: 0,
      currency: "",
    },
  ];
  const [categoriesLoading, setCategoriesLoading] = useState(true);
  const [categories, setCategories] = useState([]);

  // Top Deals
  const [topDealToursLoading, setTopDealToursLoading] = useState(true);
  const [topDealTours, setTopDealTours] = useState([]);
  const [topDealToursPriceLoading, setTopDealToursPriceLoading] =
    useState(true);
  const [topDealToursPrices, setTopDealToursPrices] =
    useState(defaultPricesValue);

  const fetchDealToursCategories = async () => {
    setCategoriesLoading(true);
    await getDealToursCategories().then((res) => {
      setCategories(res);
      setCategoriesLoading(false);
    });
  };

  const getTopDeals = async (category: string) => {
    setTopDealToursLoading(true);
    await getDealTours({
      promotionType: "black_friday",
      category,
      currency: (await getCookie("currency"))!,
      pageSize: 20,
    }).then((res) => {
      setTopDealTours(res.tours);
      setTopDealToursLoading(false);
      setTopDealToursPriceLoading(true);
      getTourPricing(
        res.tours.map((tour: any) => tour.id),
        getCookie("currency")
      ).then((res) => {
        setTopDealToursPrices(
          res.map((item: any) => {
            if (item.id === 335) {
                return { tourId: 335, price: 20, oldPrice: 40, currency: "EUR" };
            }

            if (item.id === 1010) {
                return {
                  tourId: 1010,
                  price: 79,
                  oldPrice: 177,
                  currency: "EUR",
                };
            }

            if (item.id === 2860) {
                return { tourId: 2860, price: 17, oldPrice: 34, currency: "EUR" };
            }

            return {
              tourId: item.id,
              price: item.price,
              oldPrice: item.old_price,
              currency: item.currency,
            };
          })
        );
        setTopDealToursPriceLoading(false);
      });
    });
  };

  const [subscribeLoading, setSubscribeLoading] = useState(false);
  const [subscribeMail, setSubscribeMail] = useState("");
  const [subscribeStatus, setSubscribeStatus] = useState("");
  const [subscribeErrorMessage, setSubscribeErrorMessage] = useState("");
  const isEmail = (email: string) =>
    /^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,4}$/i.test(email);

  const subscribePost = async () => {
    if (!subscribeMail || !isEmail(subscribeMail)) {
      setSubscribeErrorMessage("Please specify an email address");
      setSubscribeStatus("error");
    } else {
      setSubscribeLoading(true);
      setSubscribeStatus("");
      await postSubscribe(subscribeMail).then((res) => {
        setSubscribeMail("");
        setSubscribeStatus("success");
        setSubscribeLoading(false);
      });
    }
  };

  useEffect(() => {
    fetchDealToursCategories();
    getTopDeals("");
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  return (
    <main>
      {/* Hero */}
      <section
        className="tw-relative tw-flex tw-min-h-[37rem] tw-items-center tw-justify-center tw-overflow-hidden tw-px-6 tw-py-10"
        style={{
          backgroundImage: "url(/images/deals/black-friday.jpg)",
          backgroundRepeat: "no-repeat",
          backgroundSize: "cover",
          backgroundPosition: "left",
        }}
      >
        <div className="tw-absolute tw-inset-0 tw-bg-black/50" />
        <div className="tw-relative tw-max-w-2xl tw-text-center tw-text-white">
          <Image
            src="/images/deals/sale-ld.png"
            width={300}
            height={300}
            alt="Legendary December Sale"
            className="tw-mx-auto tw-h-auto tw-w-[220px] md:tw-w-[280px]"
          />
          <h1 className="tw-font-display tw-mt-3 tw-text-[clamp(26px,4vw,42px)] tw-font-bold tw-leading-tight">
            Top Legendary December Deals 2026/2027
          </h1>
          <p className="tw-mt-3 tw-mb-0 tw-text-sm tw-leading-relaxed tw-text-white/85">
            At the end of the year, this is how we bid farewell to it: by
            offering the best prices of the year. Kindly check the tours below
            and have fun with the Legendary December Deals. Seize the
            Season&apos;s Best Prices Now!
          </p>
        </div>
      </section>

      {/* Top deals */}
      <div className="tw-mx-auto tw-max-w-screen-xl tw-px-4 tw-py-12">
        <h2 className="tw-font-display tw-text-2xl tw-font-bold tw-text-[#14101c]">
          Discover the world with the Legendary December Deals
        </h2>
        <p className="tw-mt-2 tw-mb-6 tw-text-sm tw-leading-relaxed tw-text-[#5d556c]">
          Embark on a global exploration with unbeatable Legendary December
          deals. Immerse yourself in the wonders of Turkey with our exclusive
          offers for 2026/2027. Uncover the highlights of Istanbul, indulge in a
          Bosphorus Dinner Cruise featuring captivating dance shows, and soar
          above Cappadocia&apos;s fairy chimneys - all at incredible discounts
          of up to 90% with our Legendary December 2026/2027 deals. Browse our
          curated Legendary December travel packages below to discover and book
          the best deals of 2026/2027.
        </p>
        <div className="tw-mb-4 tw-flex tw-justify-end">
          <div className="tw-w-full sm:tw-w-64">
            {categoriesLoading && (
              <div className="tw-h-[42px] tw-w-full tw-animate-pulse tw-rounded-lg tw-bg-[#e6e2ee]" />
            )}
            {!categoriesLoading && (
              <select
                className={inputCls}
                aria-label="Categories"
                onChange={(e) => {
                  getTopDeals(e.target.value);
                }}
              >
                <option value="">All Categories</option>
                {categories.map((category: any) => (
                  <option key={category.id} value={category.slug}>
                    {category.name}
                  </option>
                ))}
              </select>
            )}
          </div>
        </div>
        {topDealToursLoading && <ToursSkeleton />}
        {!topDealToursLoading && (
          <div className="tw-grid tw-grid-cols-2 tw-gap-4 sm:tw-grid-cols-3 md:tw-grid-cols-4 lg:tw-grid-cols-5">
            {topDealTours.map((tour: any) => {
              const priceInfo = topDealToursPrices.find(
                (x: any) => x.tourId === tour.id
              );
              const hasDiscount =
                !topDealToursPriceLoading &&
                priceInfo &&
                priceInfo.oldPrice > 0 &&
                priceInfo.price != priceInfo.oldPrice;
              return (
                <div
                  key={tour.id}
                  className="tw-group tw-relative tw-flex tw-flex-col tw-overflow-hidden tw-rounded-2xl tw-border tw-border-solid tw-border-[#ece9f1] tw-bg-white tw-transition-all tw-duration-300 hover:tw--translate-y-1 hover:tw-shadow-[0_14px_34px_rgba(20,16,28,0.12)]"
                >
                  {hasDiscount && (
                    <span className="tw-absolute tw-right-3 tw-top-3 tw-z-10 tw-rounded-full tw-bg-[#dc3545] tw-px-2.5 tw-py-1 tw-text-xs tw-font-bold tw-text-white">
                      {(
                        ((priceInfo!.oldPrice - priceInfo!.price) /
                          priceInfo!.oldPrice) *
                        100
                      ).toFixed(0) + "%"}{" "}
                      Off
                    </span>
                  )}
                  <a
                    href={"/tour/" + tour.slug}
                    title={tour.name}
                    target="_blank"
                    className="tw-block tw-h-[120px] tw-overflow-hidden tw-rounded-t-2xl tw-transform-gpu md:tw-h-[150px]"
                  >
                    <Image
                      src={tour.image}
                      alt={tour.name}
                      width={300}
                      height={140}
                      className="tw-h-full tw-w-full tw-object-cover tw-transition-transform tw-duration-300 group-hover:tw-scale-105"
                      quality={100}
                      loading="lazy"
                    />
                  </a>
                  <div className="tw-flex tw-flex-1 tw-flex-col tw-p-3">
                    <a
                      href={"/tour/" + tour.slug}
                      title={tour.name}
                      target="_blank"
                      className="tw-no-underline"
                    >
                      <h3 className="tw-m-0 tw-text-sm tw-font-semibold tw-text-[#14101c] tw-transition-colors group-hover:tw-text-[#854ec9]">
                        {tour.name}
                      </h3>
                    </a>
                    <div className="tw-mt-3 tw-flex tw-items-end tw-justify-between tw-gap-2">
                      <p className="tw-m-0 tw-flex tw-items-center tw-gap-1 tw-text-xs tw-text-[#5d556c]">
                        <svg
                          xmlns="http://www.w3.org/2000/svg"
                          width="14"
                          height="14"
                          fill="currentColor"
                          viewBox="0 0 16 16"
                        >
                          <path d="M8 3.5a.5.5 0 0 0-1 0V9a.5.5 0 0 0 .252.434l3.5 2a.5.5 0 0 0 .496-.868L8 8.71V3.5z" />
                          <path d="M8 16A8 8 0 1 0 8 0a8 8 0 0 0 0 16zm7-8A7 7 0 1 1 1 8a7 7 0 0 1 14 0z" />
                        </svg>
                        {tour.duration_days == 1
                          ? "Daily"
                          : tour.duration_days + " Days"}
                      </p>
                      <div className="tw-text-right">
                        {topDealToursPriceLoading && (
                          <div className="tw-space-y-1">
                            <div className="tw-h-3 tw-w-12 tw-animate-pulse tw-rounded tw-bg-[#e6e2ee]" />
                            <div className="tw-ml-auto tw-h-3 tw-w-8 tw-animate-pulse tw-rounded tw-bg-[#e6e2ee]" />
                          </div>
                        )}
                        {!topDealToursPriceLoading && priceInfo && (
                          <>
                            {hasDiscount && (
                              <div className="tw-text-xs tw-text-[#dc3545] tw-line-through">
                                {priceFormat({
                                  amount: priceInfo.oldPrice,
                                  currency: priceInfo.currency,
                                })}
                              </div>
                            )}
                            <strong className="tw-text-sm tw-text-[#14101c]">
                              {priceFormat({
                                amount: priceInfo.price,
                                currency: priceInfo.currency,
                              })}
                            </strong>
                          </>
                        )}
                      </div>
                    </div>
                  </div>
                  <div className="tw-bg-[#14101c] tw-py-2 tw-text-center tw-text-xs tw-font-semibold tw-text-white">
                    🔥 Legendary December Deal
                  </div>
                </div>
              );
            })}
          </div>
        )}
        {!topDealToursLoading &&
          topDealTours.length === 0 &&
          "No suitable tours were found matching your search result. Please try again with another query."}
      </div>

      {/* By category */}
      <div className="tw-bg-white tw-py-12">
        <div className="tw-mx-auto tw-max-w-screen-xl tw-px-4">
          <h2 className="tw-font-display tw-text-2xl tw-font-bold tw-text-[#14101c]">
            Top Legendary December Deals by category
          </h2>
          <p className="tw-mt-2 tw-mb-6 tw-text-sm tw-leading-relaxed tw-text-[#5d556c]">
            Discover a variety of tours, must-visit destinations, and top
            tourist attractions categorized for your fun. Plus, seize the
            opportunity to enjoy exclusive Legendary December Deals on selected
            tours, saving up to 90%.
          </p>

          <div className="tw-grid tw-grid-cols-1 tw-gap-x-8 sm:tw-grid-cols-2 md:tw-grid-cols-3">
            {CATEGORY_COLUMNS.map((column, colIdx) => (
              <div
                key={colIdx}
                className={colIdx === 2 ? "tw-hidden md:tw-block" : ""}
              >
                {column.map((c) => (
                  <a
                    key={c.href}
                    href={c.href}
                    title={c.title}
                    className="tw-flex tw-items-center tw-justify-between tw-gap-2 tw-border-0 tw-border-b tw-border-solid tw-border-[#ece9f1] tw-px-1 tw-py-3.5 tw-text-sm tw-text-[#14101c] tw-no-underline tw-transition hover:tw-text-[#854ec9]"
                  >
                    <span>{c.label}</span>
                    <span className="tw-shrink-0 tw-rounded-full tw-bg-[#dc3545] tw-px-2.5 tw-py-1 tw-text-[11px] tw-font-bold tw-text-white">
                      Up to 30% Off
                    </span>
                  </a>
                ))}
              </div>
            ))}
          </div>

          <button
            className="tw-mx-auto tw-mt-10 tw-block tw-cursor-pointer tw-rounded-full tw-border-0 tw-bg-[#14101c] tw-px-8 tw-py-3.5 tw-text-sm tw-font-semibold tw-text-white tw-transition hover:tw-bg-[#2a2336]"
            type="button"
            onClick={() => {
              window.location.href =
                "/worldwide-tours#promotion_type=black_friday";
            }}
          >
            🔥 View All Legendary December Tour Deals &rarr;
          </button>
        </div>
      </div>

      {/* Newsletter */}
      <div className="tw-bg-[#14101c] tw-py-14">
        <div className="tw-mx-auto tw-grid tw-max-w-screen-xl tw-items-center tw-gap-8 tw-px-4 md:tw-grid-cols-2">
          <div className="tw-text-white">
            <h2 className="tw-font-display tw-text-2xl tw-font-bold">
              Subscribe to Our Newsletter
            </h2>
            <p className="tw-mt-2 tw-mb-0 tw-text-sm tw-text-white/80">
              Enjoy savings of up to 50% on our tours! Gain exclusive access to
              email-only offers for members.
            </p>
          </div>
          <div>
            {subscribeStatus == "error" && (
              <div
                className="tw-mb-3 tw-rounded-xl tw-border-0 tw-bg-[#fdecec] tw-px-4 tw-py-3 tw-text-sm tw-font-medium tw-text-[#b3261e]"
                role="alert"
              >
                {subscribeErrorMessage}
              </div>
            )}
            {subscribeStatus == "success" && (
              <div
                className="tw-mb-3 tw-rounded-xl tw-border-0 tw-bg-[#e8f7ee] tw-px-4 tw-py-3 tw-text-sm tw-font-medium tw-text-[#1a9c54]"
                role="alert"
              >
                Your registration has been received. We thank you.
              </div>
            )}
            <div className="tw-flex tw-overflow-hidden tw-rounded-full tw-bg-white tw-p-1">
              <input
                type="text"
                className="tw-min-w-0 tw-flex-1 tw-border-0 tw-bg-transparent tw-px-4 tw-text-sm tw-text-[#14101c] tw-outline-none"
                id="home-subscribe-mail-input"
                placeholder="Your mail"
                aria-label="Your mail"
                aria-describedby="btn-subscribe"
                autoComplete="off"
                name="subscriptmailinput"
                value={subscribeMail}
                onChange={(e) => {
                  setSubscribeMail(e.target.value);
                }}
              />
              <button
                className="tw-flex tw-items-center tw-gap-2 tw-rounded-full tw-border-0 tw-bg-[#854ec9] tw-px-6 tw-py-2.5 tw-text-sm tw-font-semibold tw-text-white tw-transition hover:tw-bg-[#6a3da4] disabled:tw-cursor-not-allowed disabled:tw-opacity-70"
                type="button"
                id="btn-subscribe"
                disabled={subscribeLoading}
                onClick={() => {
                  subscribePost();
                }}
              >
                {subscribeLoading && (
                  <span className="tw-inline-block tw-h-4 tw-w-4 tw-animate-spin tw-rounded-full tw-border-2 tw-border-solid tw-border-current tw-border-r-transparent" />
                )}
                {subscribeLoading ? "Loading..." : "Subscribe"}
              </button>
            </div>
            <p className="tw-mt-3 tw-mb-0 tw-text-xs tw-text-white/70">
              By submitting this form, I agree to the TravelShop Booking{" "}
              <a href="/terms-of-use" className="tw-text-white hover:tw-underline">
                Terms of Use
              </a>{" "}
              and{" "}
              <a
                href="/privacy-policy"
                className="tw-text-white hover:tw-underline"
              >
                Privacy Policy
              </a>
              .
            </p>
          </div>
        </div>
      </div>
    </main>
  );
}
